<?= $this->extend('admin/layout') ?><?= $this->section('content') ?><p><a class="button" href="<?= site_url('admin/students/new') ?>">Add student</a></p><form class="filters" method="get"><label>Search<input name="q" value="<?= esc($q,'attr') ?>" placeholder="ID, name, email, program, department"></label><label>Status<select name="status"><option value="">All</option><option value="enrolled" <?= $status==='enrolled'?'selected':'' ?>>Enrolled</option><option value="not_enrolled" <?= $status==='not_enrolled'?'selected':'' ?>>Not enrolled</option></select></label><button>Filter</button></form><div class="table-wrap"><table><thead><tr><th>Student ID</th><th>Name</th><th>Email</th><th>Program</th><th>Status</th></tr></thead><tbody><?php foreach($students as $s):?><tr><td><a href="<?= site_url('admin/students/'.$s['id']) ?>"><?= esc($s['student_id']) ?></a></td><td><?= esc($s['full_name']) ?></td><td><?= esc($s['institutional_email']) ?></td><td><?= esc($s['program']) ?></td><td><?= esc($s['enrollment_status']) ?></td></tr><?php endforeach ?></tbody></table></div><?= $pager->links() ?><?= $this->endSection() ?>
